extra_head_css:
.palette-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 12px; margin-top: 16px; }
    .palette-color { border-radius: var(--radius-md); overflow: hidden; border: 1px solid var(--border-color); cursor: pointer; transition: var(--transition); }
    .palette-color:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
    .palette-swatch { height: 80px; }
    .palette-info { padding: 8px 10px; background: var(--bg-card); font-size: 0.75rem; }
    .palette-info code { font-family: monospace; color: var(--accent-light); }
    .css-output { background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: var(--radius-md); padding: 16px; font-family: monospace; font-size: 0.8rem; white-space: pre-wrap; color: var(--text-secondary); margin-top: 16px; }
